// Package fixture synthesizes the Matroska/WebM, MP4, client-log and RTP
// samples the demo and tests use. Files are generated byte-for-byte by this
// code; no external media is required.
package fixture

import (
	"tracecheck/internal/ebml"
)

// Kind names a generated sample.
type Kind string

const (
	// KindHealthy is a well-formed WebM with an unknown-length Segment and
	// unknown-length Clusters, interleaved A/V blocks and a keyframe cadence.
	KindHealthy Kind = "healthy"
	// KindTruncatedBlock contains a SimpleBlock whose declared size overruns
	// the remaining bytes, so the block is truncated.
	KindTruncatedBlock Kind = "truncated-block"
	// KindBoundaryConflict has an unknown-length Cluster closed by an element
	// that is legal in no enclosing container.
	KindBoundaryConflict Kind = "boundary-conflict"
	// KindMetadataConflict has duplicate, contradictory Audio/Channels values.
	KindMetadataConflict Kind = "metadata-conflict"
)

// TrackSpec describes one generated track.
type TrackSpec struct {
	Number   uint64
	Type     uint64 // 1 video, 2 audio
	CodecID  string
	Channels uint64 // audio
	Rate     float64
	Width    uint64 // video
	Height   uint64
}

// Sample is one generated file together with the parameters used to build it.
type Sample struct {
	Kind          Kind
	Name          string // file name, e.g. "healthy.webm"
	Data          []byte
	Spec          []TrackSpec
	KeyframeEvery int
}

// DefaultSpec is the two-track A/V layout shared by the samples.
func DefaultSpec() []TrackSpec {
	return []TrackSpec{
		{Number: 1, Type: 1, CodecID: "V_VP8", Width: 320, Height: 180},
		{Number: 2, Type: 2, CodecID: "A_OPUS", Channels: 2, Rate: 48000},
	}
}

// All returns every generated sample in a stable order.
func All() []Sample {
	return []Sample{
		Healthy(),
		TruncatedBlock(),
		BoundaryConflict(),
		MetadataConflict(),
	}
}

// Healthy constructs the primary sample: two tracks, an unknown-length
// Segment, unknown-length Clusters, interleaved blocks and a regular keyframe
// cadence so keyframe lookups can be exercised.
func Healthy() Sample {
	return Sample{
		Kind:          KindHealthy,
		Name:          "healthy.webm",
		Spec:          DefaultSpec(),
		KeyframeEvery: 3,
		Data:          buildWebM(DefaultSpec(), true, true),
	}
}

// TruncatedBlock constructs a sample whose appended SimpleBlock declares more
// bytes than remain.
func TruncatedBlock() Sample {
	return Sample{
		Kind:          KindTruncatedBlock,
		Name:          "truncated-block.webm",
		Spec:          DefaultSpec(),
		KeyframeEvery: 3,
		Data:          truncatedBlockData(),
	}
}

// BoundaryConflict constructs a sample where an unknown-length Cluster is
// followed by a TrackEntry, which can close no enclosing container.
func BoundaryConflict() Sample {
	return Sample{
		Kind:          KindBoundaryConflict,
		Name:          "boundary-conflict.webm",
		Spec:          DefaultSpec(),
		KeyframeEvery: 3,
		Data:          boundaryConflictData(),
	}
}

// MetadataConflict constructs a sample whose audio track carries two
// contradictory Audio/Channels elements.
func MetadataConflict() Sample {
	return Sample{
		Kind:          KindMetadataConflict,
		Name:          "metadata-conflict.webm",
		Spec:          DefaultSpec(),
		KeyframeEvery: 3,
		Data:          metadataConflictData(),
	}
}

// buildWebM assembles a two-track WebM file with one Info, one Tracks and a
// run of Clusters. Block frames contain deterministic pseudo-media bytes so
// segment hashes are stable and each frame is distinguishable.
func buildWebM(spec []TrackSpec, unknownSegment, unknownClusters bool) []byte {
	var info ebml.Builder
	_ = info.UintElement(ebml.IDTimecodeScale, 1_000_000)
	_ = info.StringElement(ebml.IDMuxingApp, "tracecheck")
	_ = info.StringElement(ebml.IDWritingApp, "tracecheck")
	_ = info.FloatElement(ebml.IDDuration, 2000.0)

	var seg ebml.Builder
	_ = seg.Element(ebml.IDInfo, info.Bytes())
	_ = seg.Element(ebml.IDTracks, buildTracks(spec))

	// Three clusters of 400 ms each. Within a cluster: video every 150 ms and
	// audio offset +70 ms, so the two tracks interleave. Keyframe cadence is
	// handled across the whole run by a shared block counter.
	blockID := 0
	for cluster := 0; cluster < 3; cluster++ {
		var c ebml.Builder
		_ = c.UintElement(ebml.IDTimestamp, uint64(cluster*400))
		for round := 0; round < 3; round++ {
			rel := int16(round * 150)
			videoKey := blockID%3 == 0
			_ = c.Element(ebml.IDSimpleBlock,
				simpleBlockPayload(1, rel, videoKey, mediaFrame(blockID, 96)))
			blockID++
			// Audio frames are independently decodable: mark them as sync points.
			_ = c.Element(ebml.IDSimpleBlock,
				simpleBlockPayload(2, rel+70, true, mediaFrame(blockID, 64)))
			blockID++
		}
		if unknownClusters {
			_ = seg.UnknownElement(ebml.IDCluster, c.Bytes())
		} else {
			_ = seg.Element(ebml.IDCluster, c.Bytes())
		}
	}

	var top ebml.Builder
	_ = top.Container(ebml.IDEBMLHeader, func(h *ebml.Builder) error {
		if err := h.StringElement(ebml.IDDocType, "webm"); err != nil {
			return err
		}
		return h.UintElement(ebml.IDDocTypeVersion, 4)
	})
	if unknownSegment {
		_ = top.UnknownElement(ebml.IDSegment, seg.Bytes())
	} else {
		_ = top.Element(ebml.IDSegment, seg.Bytes())
	}
	return top.Bytes()
}

func buildTracks(spec []TrackSpec) []byte {
	var tracks ebml.Builder
	for _, t := range spec {
		s := t
		_ = tracks.Container(ebml.IDTrackEntry, func(e *ebml.Builder) error {
			if err := e.UintElement(ebml.IDTrackNumber, s.Number); err != nil {
				return err
			}
			if err := e.UintElement(ebml.IDTrackUID, s.Number); err != nil {
				return err
			}
			if err := e.UintElement(ebml.IDTrackType, s.Type); err != nil {
				return err
			}
			if err := e.StringElement(ebml.IDCodecID, s.CodecID); err != nil {
				return err
			}
			switch s.Type {
			case 2:
				return e.Container(ebml.IDAudio, func(a *ebml.Builder) error {
					if err := a.FloatElement(ebml.IDSamplingFrequency, s.Rate); err != nil {
						return err
					}
					if err := a.UintElement(ebml.IDChannels, s.Channels); err != nil {
						return err
					}
					return a.UintElement(ebml.IDBitDepth, 16)
				})
			case 1:
				return e.Container(ebml.IDVideo, func(v *ebml.Builder) error {
					if err := v.UintElement(ebml.IDPixelWidth, s.Width); err != nil {
						return err
					}
					if err := v.UintElement(ebml.IDPixelHeight, s.Height); err != nil {
						return err
					}
					return v.Container(ebml.IDColour, func(col *ebml.Builder) error {
						if err := col.UintElement(ebml.IDPrimaries, 1); err != nil {
							return err
						}
						return col.UintElement(ebml.IDMatrixCoeffs, 1)
					})
				})
			}
			return nil
		})
	}
	return tracks.Bytes()
}

// simpleBlockPayload encodes a Matroska SimpleBlock: track VINT, 2-byte signed
// relative timecode, flags byte, then frame bytes.
func simpleBlockPayload(track uint64, rel int16, key bool, frame []byte) []byte {
	tv, _ := ebml.EncodeVINT(track)
	out := append([]byte{}, tv...)
	out = append(out, byte(uint16(rel)>>8), byte(uint16(rel)))
	var flags byte
	if key {
		flags |= 0x80
	}
	out = append(out, flags)
	return append(out, frame...)
}

// mediaFrame returns deterministic bytes for the given block id, prefixed with
// a recognizable marker so range reads can be checked by eye.
func mediaFrame(id, size int) []byte {
	out := make([]byte, size)
	for i := range out {
		out[i] = byte((id*31 + i*7) & 0xFF)
	}
	if len(out) >= 4 {
		copy(out, []byte{'F', byte('0' + (id/10)%10), byte('0' + id%10), '#'})
	}
	return out
}
